class Solution:
    def twoCitySchedCost(self, costs: List[List[int]]) -> int:
        n = len(costs)
        m = n // 2

        @lru_cache(None)
        def dfs(cur, a):
			# cur is the current user index
			# `a` is the number of people travel to city `a`

            if cur == n:
                return 0

			# people to b city
            b = cur - a
            ans = float('inf')

			# the number of people to `a` city number did not reach to limit, 
			# then current user can trval to city `a`

            if a < m:
                ans = min(dfs(cur+1, a+1)+costs[cur][0], ans)

			# the number of people to `b` city number did not reach to limit
			# then current user can trval to city `b`
            if b < m:
                ans = min(dfs(cur+1, a)+costs[cur][1], ans)

            return ans

        return dfs(0, 0)

class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        pos, d = [0,0], "N"
        def move(d, pos, instructions):
            for i in instructions:
                if i == "G":
                    if d == "N": pos[1] += 1
                    elif d == "S": pos[1] -= 1
                    elif d == "W": pos[0] -= 1
                    else: pos[0] += 1
                elif i == "L":
                    if d == "N": d = "W"
                    elif d == "W": d = "S"
                    elif d == "S": d = "E"
                    else: d = "N"
                else:
                    if d == "N": d = "E"
                    elif d == "W": d = "N"
                    elif d == "S": d = "W"
                    else: d = "S"
            return (d, pos)
        for i in range(4):
            d, pos = (move(d, pos, instructions))
        return True if pos == [0,0] else False

class Solution:
    def prevPermOpt1(self, A):
        for left in reversed(range(len(A)-1)):
            if A[left] > A[left+1]:
                break
        else:
            return A
        right = len(A)-1
        while A[left] <= A[right]:
            right -= 1
        while A[right-1] == A[right]:
            right -= 1
        A[left], A[right] = A[right], A[left]
        return A
